		timezoneChanged := request.Timezone != nil
		enabledChanged := request.Enabled != nil && *request.Enabled != job.Enabled

		job.Expression = expression
		job.Timezone = timezoneName
		job.Enabled = enabled
		job.UpdatedAt = time.Now().UTC()

		switch {
		case !enabled:
