	f := newAPIFixture(t)
	jobID := createTestJob(t, f, "nightly")

	scheduled := "2026-10-02T01:30:00Z"
	started := "2026-10-02T01:30:05Z"
	finished := "2026-10-02T01:31:00Z"

	created := f.request(http.MethodPost, "/api/v1/jobs/"+jobID+"/runs",
