			Outcome: outcome, Error: errText,
		}); err != nil {
			t.Fatalf("create run: %v", err)
		}
	}
	mustRun("a", "r-a1", at(2, 9), "succeeded")
	mustRun("b", "r-b1", at(2, 9), "failed")
	mustRun("a", "r-a2", at(3, 8), "succeeded")
	mustRun("gone", "r-g", at(2, 10), "succeeded")
