	if _, err := st.AppendRetry("b", "r-b1", at(2, 10), at(2, 11), "succeeded", nil); err != nil {
		t.Fatalf("retry: %v", err)
	}
	if err := st.DeleteJob("gone", time.Now()); err != nil {
		t.Fatalf("delete: %v", err)
	}

