			ScheduledFor: scheduledFor,
			StartedAt:    startedAt,
			FinishedAt:   finishedAt,
			Outcome:      outcome,
			Error:        failure,
		}
		if idem != nil {
			idem.Fingerprint = fingerprint
		}
		run, err := st.CreateRunWithIdempotency(attempt, idem)
		if err != nil {
			writeRunWriteError(c, err)
			return
		}
		c.JSON(http.StatusCreated, toRunResponse(run))
